{"filePath": "/app/server.js", "content": "const express = require('express');
const { neon } = require('@neondatabase/serverless');

const app = express();
const port = process.env.APPLICATION_PORT || 8000;
const sql = neon(process.env.POSTGRES_DATABASE_URL);

const BARBERS = ['Alex', 'Lucy', 'George'];
const SLOT_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

app.use(express.json());
app.use(express.static('public'));

function validateDate(date) {
  return /^\d{4}-\d{2}-\d{2}$/.test(date);
}

function timeToMinutes(time) {
  const [h, m] = time.split(':').map(Number);
  return h * 60 + m;
}

function minutesToTime(minutes) {
  const h = String(Math.floor(minutes / 60)).padStart(2, '0');
  const m = String(minutes % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function validateSlot(date, startTime, barber) {
  if (!validateDate(date)) return 'Invalid date.';
  if (!SLOT_RE.test(startTime)) return 'Invalid start time.';
  if (!BARBERS.includes(barber)) return 'Invalid barber.';
  const minutes = timeToMinutes(startTime);
  if (minutes < 540 || minutes > 1050 || minutes % 30 !== 0) return 'Time must be a 30-minute slot from 09:00 to 17:30 UTC.';
  return null;
}

function serialize(row) {
  return {
    id: row.id,
    date: row.appointment_date,
    startTime: row.start_time.slice(0, 5),
    endTime: minutesToTime(timeToMinutes(row.start_time.slice(0, 5)) + 30),
    barber: row.barber,
    customerName: row.customer_name,
    notes: row.notes || '',
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

app.get('/api/config', (req, res) => {
  res.json({ timezone: 'UTC', open: '09:00', close: '18:00', slotDurationMinutes: 30, barbers: BARBERS });
});

app.get('/api/appointments', async (req, res) => {
  const date = String(req.query.date || '');
  if (!validateDate(date)) return res.status(400).json({ error: 'Invalid date.' });
  const rows = await sql`SELECT * FROM appointments WHERE appointment_date = ${date} ORDER BY start_time, barber`;
  res.json(rows.map(serialize));
});

app.get('/api/appointments/:id', async (req, res) => {
  const rows = await sql`SELECT * FROM appointments WHERE id = ${req.params.id}`;
  if (!rows.length) return res.status(404).json({ error: 'Appointment not found.' });
  res.json(serialize(rows[0]));
});

app.post('/api/appointments', async (req, res) => {
  const { date, startTime, barber } = req.body;
  const customerName = String(req.body.customerName || '').trim();
  const notes = String(req.body.notes || '').trim();
  const slotError = validateSlot(String(date || ''), String(startTime || ''), String(barber || ''));
  if (slotError) return res.status(400).json({ error: slotError });
  if (!customerName) return res.status(400).json({ error: 'Customer name is required.' });
  try {
    const rows = await sql`INSERT INTO appointments (appointment_date, start_time, barber, customer_name, notes) VALUES (${date}, ${startTime}, ${barber}, ${customerName}, ${notes}) RETURNING *`;
    res.status(201).json(serialize(rows[0]));
  } catch (error) {
    if (error.code === '23505') return res.status(409).json({ error: 'That slot was just booked by someone else.' });
    throw error;
  }
});

app.put('/api/appointments/:id', async (req, res) => {
  const customerName = String(req.body.customerName || '').trim();
  const notes = String(req.body.notes || '').trim();
  if (!customerName) return res.status(400).json({ error: 'Customer name is required.' });
  const rows = await sql`UPDATE appointments SET customer_name = ${customerName}, notes = ${notes}, updated_at = now() WHERE id = ${req.params.id} RETURNING *`;
  if (!rows.length) return res.status(404).json({ error: 'Appointment not found.' });
  res.json(serialize(rows[0]));
});

app.delete('/api/appointments/:id', async (req, res) => {
  const rows = await sql`DELETE FROM appointments WHERE id = ${req.params.id} RETURNING id`;
  if (!rows.length) return res.status(404).json({ error: 'Appointment not found.' });
  res.status(204).end();
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Unexpected server error.' });
});

app.listen(port, '0.0.0.0', () => {
  console.log(`Barber scheduler listening on ${port}`);
});
"}

{"filePath": "/app/scripts/setup-db.js", "content": "const { neon } = require('@neondatabase/serverless');

async function main() {
  if (!process.env.POSTGRES_DATABASE_URL) throw new Error('POSTGRES_DATABASE_URL is required');
  const sql = neon(process.env.POSTGRES_DATABASE_URL);
  await sql`CREATE TABLE IF NOT EXISTS appointments (
    id BIGSERIAL PRIMARY KEY,
    appointment_date DATE NOT NULL,
    start_time TIME NOT NULL,
    barber TEXT NOT NULL CHECK (barber IN ('Alex', 'Lucy', 'George')),
    customer_name TEXT NOT NULL CHECK (length(trim(customer_name)) > 0),
    notes TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (appointment_date, start_time, barber)
  )`;
  await sql`CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments (appointment_date)`;
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
"}

