{"filePath": "/app/public/app.js", "content": "const barbers = ['Alex', 'Lucy', 'George'];
const slots = Array.from({ length: 18 }, (_, i) => {
  const minutes = 9 * 60 + i * 30;
  return `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
});

const datePicker = document.querySelector('#datePicker');
const scheduleGrid = document.querySelector('#scheduleGrid');
const scheduleDateText = document.querySelector('#scheduleDateText');
const todayButton = document.querySelector('#todayButton');
const message = document.querySelector('#message');
const dialog = document.querySelector('#appointmentDialog');
const form = document.querySelector('#appointmentForm');
const modalMode = document.querySelector('#modalMode');
const modalTitle = document.querySelector('#modalTitle');
const detailDate = document.querySelector('#detailDate');
const detailTime = document.querySelector('#detailTime');
const detailBarber = document.querySelector('#detailBarber');
const customerName = document.querySelector('#customerName');
const notes = document.querySelector('#notes');
const formError = document.querySelector('#formError');
const cancelAppointment = document.querySelector('#cancelAppointment');
const closeDialog = document.querySelector('#closeDialog');

let appointments = [];
let selected = null;

function todayUtc() {
  return new Date().toISOString().slice(0, 10);
}

function endTime(start) {
  const [h, m] = start.split(':').map(Number);
  const minutes = h * 60 + m + 30;
  return `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
}

function showMessage(text, isError = false) {
  message.textContent = text;
  message.hidden = !text;
  message.classList.toggle('error', isError);
}

function showFormError(text) {
  formError.textContent = text;
  formError.hidden = !text;
}

async function request(path, options) {
  const response = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...options });
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    throw new Error(body.error || 'Request failed.');
  }
  if (response.status === 204) return null;
  return response.json();
}

async function loadSchedule() {
  showMessage('');
  scheduleDateText.textContent = `${datePicker.value} · UTC`;
  try {
    appointments = await request(`/api/appointments?date=${encodeURIComponent(datePicker.value)}`);
    renderGrid();
  } catch (error) {
    showMessage(error.message, true);
  }
}

function appointmentFor(time, barber) {
  return appointments.find((item) => item.startTime === time && item.barber === barber);
}

function renderGrid() {
  scheduleGrid.innerHTML = '';
  scheduleGrid.appendChild(cell('', 'cell header', 'text-corner-header'));
  barbers.forEach((barber) => scheduleGrid.appendChild(cell(barber, 'cell header', `text-barber-${barber}`)));
  slots.forEach((slot) => {
    scheduleGrid.appendChild(cell(slot, 'cell time', `text-time-${slot.replace(':', '')}`));
    barbers.forEach((barber) => {
      const wrapper = cell('', 'cell', `cell-${barber}-${slot.replace(':', '')}`);
      const appointment = appointmentFor(slot, barber);
      if (appointment) {
        const button = document.createElement('button');
        button.className = 'appointment';
        button.type = 'button';
        button.dataset.testid = `button-appointment-${appointment.id}`;
        button.innerHTML = `<span data-testid="text-customer-${appointment.id}"></span><small data-testid="text-appointment-time-${appointment.id}">${slot}-${endTime(slot)}</small>`;
        button.querySelector('span').textContent = appointment.customerName;
        button.addEventListener('click', () => openExisting(appointment));
        wrapper.appendChild(button);
      } else {
        const button = document.createElement('button');
        button.className = 'slot';
        button.type = 'button';
        button.dataset.testid = `button-empty-slot-${barber}-${slot.replace(':', '')}`;
        button.textContent = 'Available';
        button.addEventListener('click', () => openNew(slot, barber));
        wrapper.appendChild(button);
      }
      scheduleGrid.appendChild(wrapper);
    });
  });
}

function cell(text, className, testId) {
  const div = document.createElement('div');
  div.className = className;
  div.dataset.testid = testId;
  div.textContent = text;
  return div;
}

function fillDetails(date, startTime, barber) {
  detailDate.textContent = date;
  detailTime.textContent = `${startTime}-${endTime(startTime)}`;
  detailBarber.textContent = barber;
}

function openNew(startTime, barber) {
  selected = { mode: 'new', date: datePicker.value, startTime, barber };
  modalMode.textContent = 'Add appointment';
  modalTitle.textContent = 'Book an empty slot';
  customerName.value = '';
  notes.value = '';
  cancelAppointment.hidden = true;
  fillDetails(selected.date, startTime, barber);
  showFormError('');
  dialog.showModal();
  customerName.focus();
}

function openExisting(appointment) {
  selected = { mode: 'edit', ...appointment };
  modalMode.textContent = 'Appointment details';
  modalTitle.textContent = appointment.customerName;
  customerName.value = appointment.customerName;
  notes.value = appointment.notes || '';
  cancelAppointment.hidden = false;
  fillDetails(appointment.date, appointment.startTime, appointment.barber);
  showFormError('');
  dialog.showModal();
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  showFormError('');
  const name = customerName.value.trim();
  if (!name) return showFormError('Customer name is required.');
  const payload = { customerName: name, notes: notes.value.trim() };
  try {
    if (selected.mode === 'new') {
      await request('/api/appointments', { method: 'POST', body: JSON.stringify({ ...selected, ...payload }) });
      showMessage('Appointment booked.');
    } else {
      await request(`/api/appointments/${selected.id}`, { method: 'PUT', body: JSON.stringify(payload) });
      showMessage('Appointment updated.');
    }
    dialog.close();
    await loadSchedule();
  } catch (error) {
    showFormError(error.message);
  }
});

cancelAppointment.addEventListener('click', async () => {
  if (!selected?.id) return;
  if (!confirm('Cancel this appointment?')) return;
  try {
    await request(`/api/appointments/${selected.id}`, { method: 'DELETE' });
    dialog.close();
    showMessage('Appointment cancelled.');
    await loadSchedule();
  } catch (error) {
    showFormError(error.message);
  }
});

closeDialog.addEventListener('click', () => dialog.close());
datePicker.addEventListener('change', loadSchedule);
todayButton.addEventListener('click', () => {
  datePicker.value = todayUtc();
  loadSchedule();
});

datePicker.value = todayUtc();
loadSchedule();
"}

