async function main() {
  if (!process.env.POSTGRES_DATABASE_URL) throw new Error('POSTGRES_DATABASE_URL is required');
  const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });
  await pool.query(`CREATE TABLE IF NOT EXISTS appointments (
