{"filePath": "/app/server.js", "content": "const http = require('http');
const fs = require('fs');
const path = require('path');

const root = __dirname;
const publicDir = path.join(root, 'public');
const csvPath = path.join(root, 'assets', 'questions.csv');
const port = Number(process.env.APPLICATION_PORT || 8000);

function parseCsv(text) {
  const rows = [];
  let row = [];
  let value = '';
  let quoted = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"' && quoted && next === '"') {
      value += '"';
      i += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === ',' && !quoted) {
      row.push(value);
      value = '';
    } else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && next === '\n') i += 1;
      row.push(value);
      if (row.some((cell) => cell.length > 0)) rows.push(row);
      row = [];
      value = '';
    } else {
      value += char;
    }
  }

  if (value.length || row.length) {
    row.push(value);
    if (row.some((cell) => cell.length > 0)) rows.push(row);
  }

  const headers = rows.shift() || [];
  return rows.map((cells) => Object.fromEntries(headers.map((header, index) => [header, cells[index] || ''])));
}

function loadQuestions() {
  const text = fs.readFileSync(csvPath, 'utf8');
  return parseCsv(text).map((item) => ({
    id: item.id,
    question: item.question,
    options: {
      A: item.option_a,
      B: item.option_b,
      C: item.option_c,
      D: item.option_d,
    },
    correctOption: item.correct_option,
    explanation: item.explanation,
    category: item.category,
  }));
}

function shuffle(items) {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

const questions = loadQuestions();
const categories = [...new Set(questions.map((question) => question.category))].sort((a, b) => a.localeCompare(b));

function sendJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(data));
}

function serveStatic(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const pathname = url.pathname === '/' ? '/index.html' : decodeURIComponent(url.pathname);
  const filePath = path.normalize(path.join(publicDir, pathname));

  if (!filePath.startsWith(publicDir)) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }

  fs.readFile(filePath, (error, content) => {
    if (error) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const types = {
      '.html': 'text/html; charset=utf-8',
      '.css': 'text/css; charset=utf-8',
      '.js': 'text/javascript; charset=utf-8',
      '.svg': 'image/svg+xml',
    };
    res.writeHead(200, { 'Content-Type': types[ext] || 'application/octet-stream' });
    res.end(content);
  });
}

function handleApi(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

  if (url.pathname === '/api/categories') {
    sendJson(res, 200, {
      categories: categories.map((category) => ({
        name: category,
        count: questions.filter((question) => question.category === category).length,
      })),
    });
    return;
  }

  if (url.pathname === '/api/quiz') {
    const surprise = url.searchParams.get('surprise') === 'true';
    let category = url.searchParams.get('category');

    if (surprise) category = categories[Math.floor(Math.random() * categories.length)];
    if (!category || !categories.includes(category)) {
      sendJson(res, 400, { error: 'Invalid category' });
      return;
    }

    const pool = questions.filter((question) => question.category === category);
    sendJson(res, 200, {
      category,
      warning: pool.length < 10 ? 'Not enough questions in this category for all accomplishments' : '',
      questions: shuffle(pool).slice(0, 10),
    });
    return;
  }

  sendJson(res, 404, { error: 'Not found' });
}

const server = http.createServer((req, res) => {
  if (req.url.startsWith('/api/')) handleApi(req, res);
  else serveStatic(req, res);
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Quiz application listening on port ${port}`);
});
"}

