{"filePath": "/app/public/app.js", "content": "const screens = {
  category: document.getElementById('category-screen'),
  warning: document.getElementById('warning-screen'),
  quiz: document.getElementById('quiz-screen'),
  results: document.getElementById('results-screen'),
};

const state = {
  categories: [],
  category: '',
  questions: [],
  pendingQuestions: [],
  index: 0,
  score: 0,
  streak: 0,
  maxStreak: 0,
  answered: false,
  startedAt: 0,
  elapsed: 0,
};

const letters = ['A', 'B', 'C', 'D'];

function showScreen(name) {
  Object.entries(screens).forEach(([key, element]) => element.classList.toggle('hidden', key !== name));
}

function testIdSafe(value) {
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

async function getJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error('Request failed');
  return response.json();
}

async function loadCategories() {
  const data = await getJson('/api/categories');
  state.categories = data.categories;
  renderCategories();
}

function renderCategories() {
  const grid = document.getElementById('category-grid');
  grid.innerHTML = '';

  const surprise = document.createElement('button');
  surprise.className = 'category-card surprise';
  surprise.dataset.testid = 'button-surprise-me';
  surprise.innerHTML = '<strong data-testid="text-category-surprise-title">Surprise Me!</strong><span data-testid="text-category-surprise-description">Randomly select a category</span>';
  surprise.addEventListener('click', () => startQuiz('', true));
  grid.appendChild(surprise);

  state.categories.forEach((category) => {
    const card = document.createElement('button');
    const id = testIdSafe(category.name);
    card.className = 'category-card';
    card.dataset.testid = `button-category-${id}`;
    card.innerHTML = `<strong data-testid="text-category-name-${id}">${category.name}</strong><span data-testid="text-category-count-${id}">${category.count} questions</span>`;
    card.addEventListener('click', () => startQuiz(category.name, false));
    grid.appendChild(card);
  });
}

async function startQuiz(category, surprise) {
  const params = surprise ? '?surprise=true' : `?category=${encodeURIComponent(category)}`;
  const data = await getJson(`/api/quiz${params}`);
  state.category = data.category;
  state.pendingQuestions = data.questions;

  if (surprise) {
    document.getElementById('warning-category').textContent = `Surprise Me selected ${data.category}`;
  } else {
    document.getElementById('warning-category').textContent = data.category;
  }

  if (data.warning) {
    showScreen('warning');
    return;
  }

  beginRound(data.questions);
}

function beginRound(questions) {
  state.questions = questions;
  state.index = 0;
  state.score = 0;
  state.streak = 0;
  state.maxStreak = 0;
  state.answered = false;
  state.startedAt = Date.now();
  showScreen('quiz');
  renderQuestion();
}

function renderQuestion() {
  const question = state.questions[state.index];
  state.answered = false;
  document.getElementById('progress').textContent = `Question ${state.index + 1} of ${state.questions.length}`;
  document.getElementById('quiz-category').textContent = state.category;
  document.getElementById('progress-fill').style.width = `${((state.index + 1) / state.questions.length) * 100}%`;
  document.getElementById('question-text').textContent = question.question;
  document.getElementById('feedback').className = 'feedback hidden';
  document.getElementById('feedback').textContent = '';
  document.getElementById('explanation').className = 'explanation hidden';
  document.getElementById('explanation').textContent = '';
  document.getElementById('button-next').classList.add('hidden');
  document.getElementById('button-next').textContent = state.index === state.questions.length - 1 ? 'See Results' : 'Next Question';

  const options = document.getElementById('options');
  options.innerHTML = '';
  letters.forEach((letter) => {
    const button = document.createElement('button');
    button.className = 'option';
    button.dataset.testid = `button-answer-${letter.toLowerCase()}`;
    button.innerHTML = `<span class="letter" data-testid="text-option-letter-${letter.toLowerCase()}">${letter}</span><span data-testid="text-option-${letter.toLowerCase()}">${question.options[letter]}</span>`;
    button.addEventListener('click', () => submitAnswer(letter));
    options.appendChild(button);
  });
}

function submitAnswer(letter) {
  if (state.answered) return;
  state.answered = true;
  const question = state.questions[state.index];
  const correct = letter === question.correctOption;

  if (correct) {
    state.score += 1;
    state.streak += 1;
    state.maxStreak = Math.max(state.maxStreak, state.streak);
  } else {
    state.streak = 0;
  }

  [...document.querySelectorAll('.option')].forEach((button) => {
    const option = button.dataset.testid.replace('button-answer-', '').toUpperCase();
    button.disabled = true;
    if (option === question.correctOption) button.classList.add('correct');
    if (option === letter && !correct) button.classList.add('incorrect');
  });

  const feedback = document.getElementById('feedback');
  feedback.className = `feedback ${correct ? 'correct' : 'incorrect'}`;
  feedback.textContent = correct ? 'Correct!' : 'Incorrect';
  document.getElementById('explanation').classList.remove('hidden');
  document.getElementById('explanation').textContent = question.explanation;
  document.getElementById('button-next').classList.remove('hidden');
}

function nextQuestion() {
  if (state.index === state.questions.length - 1) {
    showResults();
    return;
  }
  state.index += 1;
  renderQuestion();
}

function showResults() {
  state.elapsed = Math.max(0, Math.round((Date.now() - state.startedAt) / 1000));
  const total = state.questions.length;
  const percent = Math.round((state.score / total) * 100);
  document.getElementById('score').textContent = `${state.score}/${total} Correct (${percent}%)`;
  document.getElementById('elapsed').textContent = `Elapsed time: ${state.elapsed} seconds`;
  renderAchievements(total);
  showScreen('results');
}

function renderAchievements(total) {
  const achievements = [];
  if (total === 10 && state.score === total) achievements.push('Perfect Round');
  if (state.maxStreak >= 5) achievements.push('Hot Streak');
  if (state.maxStreak >= 3) achievements.push('Triple Win');

  const container = document.getElementById('achievements');
  container.innerHTML = '';
  if (!achievements.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-achievement';
    empty.dataset.testid = 'text-no-achievements';
    empty.textContent = 'No achievements this round';
    container.appendChild(empty);
    return;
  }

  achievements.forEach((achievement) => {
    const item = document.createElement('div');
    item.className = 'achievement';
    item.dataset.testid = `text-achievement-${testIdSafe(achievement)}`;
    item.textContent = achievement;
    container.appendChild(item);
  });
}

function newCategory() {
  showScreen('category');
}

document.getElementById('button-proceed').addEventListener('click', () => beginRound(state.pendingQuestions));
document.getElementById('button-back-warning').addEventListener('click', newCategory);
document.getElementById('button-next').addEventListener('click', nextQuestion);
document.getElementById('button-play-again').addEventListener('click', () => startQuiz(state.category, false));
document.getElementById('button-new-category').addEventListener('click', newCategory);

loadCategories().catch(() => {
  document.getElementById('category-grid').innerHTML = '<p data-testid="status-load-error">Unable to load questions.</p>';
});
"}

