{"filePath": "/app/server.js", "content": "const crypto = require('crypto');
const express = require('express');
const { Pool } = require('pg');

const PASSWORD = 'my-notes-are-mine';
const tokens = new Set();
const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });

async function migrate() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS notes (
      id UUID PRIMARY KEY,
      body TEXT NOT NULL DEFAULT '',
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    )
  `);
}

function requireAuth(req, res, next) {
  const header = req.get('authorization') || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : '';
  if (!tokens.has(token)) return res.status(401).json({ error: 'Locked' });
  next();
}

function noteResponse(row) {
  return {
    id: row.id,
    body: row.body,
    updatedAt: new Date(row.updated_at).toISOString(),
  };
}

async function main() {
  await migrate();
  if (process.argv.includes('--migrate')) {
    await pool.end();
    return;
  }

  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '1mb' }));
  app.use(express.static('public'));

  app.post('/api/unlock', (req, res) => {
    if (!req.body || typeof req.body.password !== 'string' || req.body.password.length === 0) {
      return res.status(400).json({ error: 'Password is required' });
    }
    if (req.body.password !== PASSWORD) return res.status(401).json({ error: 'Incorrect password' });
    const token = crypto.randomBytes(32).toString('hex');
    tokens.add(token);
    res.json({ token });
  });

  app.get('/api/notes', requireAuth, async (_req, res, next) => {
    try {
      const { rows } = await pool.query('SELECT id, body, updated_at FROM notes ORDER BY updated_at DESC');
      res.json(rows.map(noteResponse));
    } catch (error) {
      next(error);
    }
  });

  app.post('/api/notes', requireAuth, async (_req, res, next) => {
    try {
      const id = crypto.randomUUID();
      const { rows } = await pool.query('INSERT INTO notes (id, body, updated_at) VALUES ($1, $2, NOW()) RETURNING id, body, updated_at', [id, '']);
      res.status(201).json(noteResponse(rows[0]));
    } catch (error) {
      next(error);
    }
  });

  app.get('/api/notes/:id', requireAuth, async (req, res, next) => {
    try {
      const { rows } = await pool.query('SELECT id, body, updated_at FROM notes WHERE id = $1', [req.params.id]);
      if (!rows.length) return res.status(404).json({ error: 'Note not found' });
      res.json(noteResponse(rows[0]));
    } catch (error) {
      next(error);
    }
  });

  app.put('/api/notes/:id', requireAuth, async (req, res, next) => {
    try {
      const body = typeof req.body.body === 'string' ? req.body.body : '';
      const { rows } = await pool.query('UPDATE notes SET body = $1, updated_at = NOW() WHERE id = $2 RETURNING id, body, updated_at', [body, req.params.id]);
      if (!rows.length) return res.status(404).json({ error: 'Note not found' });
      res.json(noteResponse(rows[0]));
    } catch (error) {
      next(error);
    }
  });

  app.delete('/api/notes/:id', requireAuth, async (req, res, next) => {
    try {
      await pool.query('DELETE FROM notes WHERE id = $1', [req.params.id]);
      res.status(204).end();
    } catch (error) {
      next(error);
    }
  });

  app.get('*splat', (_req, res) => res.sendFile(__dirname + '/public/index.html'));

  app.use((error, _req, res, _next) => {
    console.error(error);
    res.status(500).json({ error: 'Server error' });
  });

  const port = Number(process.env.APPLICATION_PORT || 8000);
  app.listen(port, '0.0.0.0', () => console.log(`Notes app listening on ${port}`));
}

main().catch(async (error) => {
  console.error(error);
  await pool.end();
  process.exit(1);
});
"}

{"filePath": "/app/public/styles.css", "content": ":root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #eef2ff;
  color: #172033;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(124, 58, 237, 0.22), transparent 34rem),
    radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 30rem),
    linear-gradient(135deg, #f8fafc 0%, #eef2ff 100%);
}

button, input, textarea {
  font: inherit;
}

button {
  border: 0;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.shell {
  width: min(1120px, calc(100vw - 32px));
  margin: 0 auto;
  padding: 32px 0;
}

.gate-wrap {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
}

.gate-card, .panel {
  background: rgba(255, 255, 255, 0.86);
  border: 1px solid rgba(148, 163, 184, 0.24);
  box-shadow: 0 24px 70px rgba(79, 70, 229, 0.16);
  backdrop-filter: blur(18px);
}

.gate-card {
  width: min(460px, 100%);
  border-radius: 32px;
  padding: 38px;
}

.kicker {
  margin: 0 0 10px;
  color: #6366f1;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  color: #111827;
  font-size: clamp(2rem, 6vw, 4rem);
  letter-spacing: -0.06em;
  line-height: 0.96;
}

.subtitle {
  margin: 16px 0 28px;
  color: #64748b;
  line-height: 1.6;
}

.field {
  display: grid;
  gap: 9px;
  color: #334155;
  font-weight: 700;
}

.input, .textarea {
  width: 100%;
  border: 1px solid #dbe3ef;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.9);
  color: #0f172a;
  outline: none;
  transition: border 0.18s, box-shadow 0.18s, transform 0.18s;
}

.input {
  height: 52px;
  padding: 0 18px;
}

.input:focus, .textarea:focus {
  border-color: #818cf8;
  box-shadow: 0 0 0 5px rgba(99, 102, 241, 0.14);
}

.primary, .secondary, .danger, .ghost {
  min-height: 44px;
  border-radius: 16px;
  padding: 0 18px;
  font-weight: 800;
  transition: transform 0.18s, box-shadow 0.18s, background 0.18s;
}

.primary:hover, .secondary:hover, .danger:hover, .ghost:hover, .note-card:hover {
  transform: translateY(-1px);
}

.primary {
  width: 100%;
  margin-top: 18px;
  color: white;
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  box-shadow: 0 16px 32px rgba(79, 70, 229, 0.28);
}

.secondary {
  color: white;
  background: linear-gradient(135deg, #0f172a, #334155);
}

.danger {
  color: white;
  background: linear-gradient(135deg, #e11d48, #be123c);
}

.ghost {
  color: #475569;
  background: #eef2ff;
}

.error {
  margin: 12px 0 0;
  color: #be123c;
  font-weight: 800;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 18px;
  margin-bottom: 26px;
}

.toolbar {
  display: flex;
  gap: 12px;
  align-items: center;
}

.panel {
  border-radius: 30px;
  padding: 22px;
}

.search-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 14px;
  margin-bottom: 18px;
}

.notes-list {
  display: grid;
  gap: 12px;
}

.note-card {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 14px;
  width: 100%;
  text-align: left;
  border: 1px solid #e2e8f0;
  border-radius: 22px;
  padding: 18px;
  background: white;
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.06);
  transition: transform 0.18s, box-shadow 0.18s, border 0.18s;
}

.note-card:hover {
  border-color: #c4b5fd;
  box-shadow: 0 16px 34px rgba(79, 70, 229, 0.12);
}

.note-title {
  margin: 0 0 6px;
  color: #111827;
  font-size: 1.08rem;
  font-weight: 900;
}

.note-preview, .empty, .timestamp {
  color: #64748b;
}

.note-preview {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.timestamp {
  white-space: nowrap;
  font-size: 0.88rem;
  font-weight: 800;
}

.empty {
  border: 1px dashed #cbd5e1;
  border-radius: 22px;
  padding: 34px;
  text-align: center;
  background: rgba(255,255,255,0.7);
}

.editor-panel {
  display: grid;
  gap: 16px;
}

.textarea {
  min-height: calc(100vh - 230px);
  resize: vertical;
  padding: 20px;
  line-height: 1.6;
  border-radius: 24px;
  box-shadow: inset 0 2px 8px rgba(15, 23, 42, 0.04);
}

.status {
  color: #64748b;
  font-size: 0.92rem;
  font-weight: 700;
}

@media (max-width: 720px) {
  .topbar, .search-row, .note-card {
    grid-template-columns: 1fr;
    display: grid;
    align-items: stretch;
  }

  .toolbar {
    flex-wrap: wrap;
  }

  .gate-card {
    padding: 28px;
  }
}
"}

{"filePath": "/app/public/app.js", "content": "const app = document.getElementById('app');
let token = null;
let notes = [];
let currentNote = null;
let draft = '';
let dirty = false;
let saving = false;

const api = async (path, options = {}) => {
  const response = await fetch(path, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {}),
    },
  });
  if (response.status === 204) return null;
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
};

const escapeHtml = (value) => value.replace(/[&<>"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[character]));

const titleFor = (body) => {
  const line = body.split('\n').find((part) => part.trim().length > 0);
  return line ? line.trim() : 'New Note';
};

const previewFor = (body) => {
  const lines = body.split('\n');
  const titleIndex = lines.findIndex((part) => part.trim().length > 0);
  const rest = lines.slice(titleIndex === -1 ? 0 : titleIndex + 1).join(' ').trim();
  return rest || 'No additional text';
};

const formatUtc = (value) => {
  const date = new Date(value);
  const pad = (number) => String(number).padStart(2, '0');
  return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}`;
};

const setRoute = (path) => {
  history.pushState(null, '', path);
  route();
};

const saveCurrent = async () => {
  if (!currentNote || !dirty || saving) return;
  saving = true;
  renderSaveStatus('Saving...');
  try {
    const saved = await api(`/api/notes/${currentNote.id}`, { method: 'PUT', body: JSON.stringify({ body: draft }) });
    notes = notes.map((note) => note.id === saved.id ? saved : note);
    currentNote = saved;
    dirty = false;
    renderSaveStatus(`Saved ${formatUtc(saved.updatedAt)}`);
  } catch (error) {
    renderSaveStatus(error.message);
  } finally {
    saving = false;
  }
};

const renderSaveStatus = (text) => {
  const el = document.querySelector('[data-testid="status-save"]');
  if (el) el.textContent = text;
};

const loadNotes = async () => {
  notes = await api('/api/notes');
};

const unlockView = (message = '') => {
  app.innerHTML = `
    <section class="gate-wrap" data-testid="section-password-gate">
      <form class="gate-card" data-testid="form-unlock">
        <p class="kicker" data-testid="text-app-label">Private notes</p>
        <h1 data-testid="text-gate-title">Unlock your space</h1>
        <p class="subtitle" data-testid="text-gate-description">Enter the password to open this tab's notes session.</p>
        <label class="field" data-testid="label-password">Password
          <input class="input" data-testid="input-password" type="password" autocomplete="current-password" autofocus>
        </label>
        <button class="primary" data-testid="button-unlock" type="submit">Unlock</button>
        <p class="error" data-testid="text-unlock-error">${escapeHtml(message)}</p>
      </form>
    </section>
  `;
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const password = input.value;
    if (!password) return unlockView('Password is required');
    try {
      const result = await api('/api/unlock', { method: 'POST', body: JSON.stringify({ password }) });
      token = result.token;
      await loadNotes();
      route();
    } catch (error) {
      unlockView(error.message);
    }
  });
};

const listView = () => {
  const query = new URLSearchParams(location.search).get('q') || '';
  const filtered = notes.filter((note) => {
    const haystack = `${titleFor(note.body)} ${note.body}`.toLowerCase();
    return haystack.includes(query.toLowerCase());
  });
  app.innerHTML = `
    <section class="shell" data-testid="section-notes-list">
      <header class="topbar">
        <div>
          <p class="kicker" data-testid="text-list-label">Notes</p>
          <h1 data-testid="text-list-title">Your notes</h1>
          <p class="subtitle" data-testid="text-note-count">${filtered.length} of ${notes.length} notes</p>
        </div>
        <button class="secondary" data-testid="button-new-note" type="button">New Note</button>
      </header>
      <section class="panel" data-testid="section-list-panel">
        <div class="search-row">
          <input class="input" data-testid="input-search" type="search" placeholder="Search title or body" value="${escapeHtml(query)}">
          <button class="ghost" data-testid="button-clear-search" type="button">Clear</button>
        </div>
        <div class="notes-list" data-testid="list-notes">
          ${filtered.length ? filtered.map(noteCard).join('') : `<div class="empty" data-testid="text-empty-state">No notes found. Create a new note to begin.</div>`}
        </div>
      </section>
    </section>
  `;
  app.querySelector('[data-testid="button-new-note"]').addEventListener('click', createNote);
  app.querySelector('[data-testid="input-search"]').addEventListener('input', (event) => {
    const value = event.target.value;
    history.replaceState(null, '', value ? `/?q=${encodeURIComponent(value)}` : '/');
    listView();
  });
  app.querySelector('[data-testid="button-clear-search"]').addEventListener('click', () => setRoute('/'));
  app.querySelectorAll('[data-note-id]').forEach((card) => {
    card.addEventListener('click', (event) => {
      if (event.target.closest('button')) return;
      setRoute(`/notes/${card.dataset.noteId}`);
    });
  });
  app.querySelectorAll('[data-delete-id]').forEach((button) => button.addEventListener('click', () => deleteNote(button.dataset.deleteId, false)));
};

const noteCard = (note) => `
  <button class="note-card" data-testid="card-note-${note.id}" data-note-id="${note.id}" type="button">
    <span>
      <span class="note-title" data-testid="text-title-${note.id}">${escapeHtml(titleFor(note.body))}</span>
      <span class="note-preview" data-testid="text-preview-${note.id}">${escapeHtml(previewFor(note.body))}</span>
    </span>
    <span class="toolbar">
      <span class="timestamp" data-testid="text-timestamp-${note.id}">${formatUtc(note.updatedAt)}</span>
      <span class="danger" role="button" tabindex="0" data-testid="button-delete-${note.id}" data-delete-id="${note.id}">Delete</span>
    </span>
  </button>
`;

const createNote = async () => {
  const note = await api('/api/notes', { method: 'POST' });
  notes = [note, ...notes];
  setRoute(`/notes/${note.id}`);
};

const editorView = async (id) => {
  if (dirty) await saveCurrent();
  try {
    currentNote = notes.find((note) => note.id === id) || await api(`/api/notes/${id}`);
  } catch (_error) {
    setRoute('/');
    return;
  }
  draft = currentNote.body;
  dirty = false;
  app.innerHTML = `
    <section class="shell" data-testid="section-editor">
      <header class="topbar">
        <div>
          <p class="kicker" data-testid="text-editor-label">Editing</p>
          <h1 data-testid="text-editor-title">${escapeHtml(titleFor(draft))}</h1>
          <p class="subtitle" data-testid="text-editor-timestamp">Last edited ${formatUtc(currentNote.updatedAt)}</p>
        </div>
        <div class="toolbar">
          <button class="ghost" data-testid="button-back" type="button">Back to list</button>
          <button class="danger" data-testid="button-delete-current" type="button">Delete</button>
        </div>
      </header>
      <section class="panel editor-panel" data-testid="section-editor-panel">
        <textarea class="textarea" data-testid="input-note-body" placeholder="Start typing...">${escapeHtml(draft)}</textarea>
        <div class="status" data-testid="status-save">Saved ${formatUtc(currentNote.updatedAt)}</div>
      </section>
    </section>
  `;
  const textarea = app.querySelector('textarea');
  textarea.focus();
  textarea.setSelectionRange(textarea.value.length, textarea.value.length);
  textarea.addEventListener('input', () => {
    draft = textarea.value;
    dirty = true;
    renderSaveStatus('Unsaved changes');
    const title = app.querySelector('[data-testid="text-editor-title"]');
    if (title) title.textContent = titleFor(draft);
  });
  app.querySelector('[data-testid="button-back"]').addEventListener('click', async () => {
    await saveCurrent();
    currentNote = null;
    setRoute('/');
  });
  app.querySelector('[data-testid="button-delete-current"]').addEventListener('click', () => deleteNote(id, true));
};

const deleteNote = async (id, fromEditor) => {
  if (!confirm('Permanently delete this note? This cannot be undone.')) return;
  await api(`/api/notes/${id}`, { method: 'DELETE' });
  notes = notes.filter((note) => note.id !== id);
  if (fromEditor || (currentNote && currentNote.id === id)) {
    currentNote = null;
    dirty = false;
    setRoute('/');
  } else {
    listView();
  }
};

const route = async () => {
  if (!token) return unlockView();
  const match = location.pathname.match(/^\/notes\/([^/]+)$/);
  if (match) return editorView(match[1]);
  if (dirty) await saveCurrent();
  currentNote = null;
  listView();
};

window.addEventListener('popstate', route);
window.addEventListener('beforeunload', (event) => {
  if (!dirty || !currentNote) return;
  const xhr = new XMLHttpRequest();
  xhr.open('PUT', `/api/notes/${currentNote.id}`, false);
  xhr.setRequestHeader('Content-Type', 'application/json');
  xhr.setRequestHeader('Authorization', `Bearer ${token}`);
  xhr.send(JSON.stringify({ body: draft }));
  event.preventDefault();
});

route();
"}

