app.get('/api/search', async (req, res) => {
  const postcode = String(req.query.postcode || '').toUpperCase()
  const date = req.query.date
  const guests = Number(req.query.guests || 0)
  if (!postcode || !date || !guests) return res.status(400).json({ error: 'Postcode, date, and guest count are required' })
  const pc = await query('SELECT * FROM postcodes WHERE postcode=$1', [postcode])
  if (!pc.rows[0]) return res.status(400).json({ error: 'Unknown postcode' })
  const { rows } = await query(`SELECT v.*, p.latitude, p.longitude FROM venues v JOIN postcodes p ON p.postcode=v.postcode
    WHERE v.status='Active' AND $1 BETWEEN v.min_guests AND v.max_guests
    AND NOT EXISTS (SELECT 1 FROM venue_dates d WHERE d.venue_id=v.id AND d.date=$2 AND d.status IN ('Blocked','Booked'))`, [guests, date])
  let results = rows.map(v => ({ ...v, distance: miles(Number(pc.rows[0].latitude), Number(pc.rows[0].longitude), Number(v.latitude), Number(v.longitude)), price: Number(v.base_fee) + Number(v.per_person_fee) * guests }))
    .filter(v => v.distance <= 30)
  if (req.query.type === 'Indoor') results = results.filter(v => ['Indoor', 'Both'].includes(v.venue_type))
  if (req.query.type === 'Outdoor') results = results.filter(v => ['Outdoor', 'Both'].includes(v.venue_type))
  if (req.query.minPrice) results = results.filter(v => v.price >= Number(req.query.minPrice))
  if (req.query.maxPrice) results = results.filter(v => v.price <= Number(req.query.maxPrice))
  results.sort((a, b) => req.query.sort === 'price' ? a.price - b.price : a.distance - b.distance)
  res.json({ results })
})

