app.post('/api/venues/:id/dates', requireUser, async (req, res) => {
  const user = await currentUser(req)
  const owner = await query('SELECT 1 FROM venues WHERE id=$1 AND manager_id=$2', [req.params.id, user.id])
  if (!owner.rows[0]) return res.status(403).json({ error: 'Venue manager only' })
  const existing = await query('SELECT immutable FROM venue_dates WHERE venue_id=$1 AND date=$2', [req.params.id, req.body.date])
  if (existing.rows[0]?.immutable) return res.status(400).json({ error: 'Booked dates are immutable' })
  await query(`INSERT INTO venue_dates(venue_id,date,status,note,immutable) VALUES($1,$2,'Blocked',$3,false)
    ON CONFLICT(venue_id,date) DO UPDATE SET status='Blocked',note=EXCLUDED.note WHERE venue_dates.immutable=false`, [req.params.id, req.body.date, req.body.note || null])
