  if (overlap.rows[0]) return res.status(400).json({ error: 'Overlapping slot exists' })
  await query('INSERT INTO tour_slots(venue_id,date,time,duration,capacity,original_capacity) VALUES($1,$2,$3,$4,$5,$5)', [req.params.id, req.body.date, req.body.time, req.body.duration, req.body.capacity])
