  res.json({ tours: tours.rows, weddings: weddings.rows })
})

app.post('/api/tour-requests/:id/:action', requireUser, async (req, res) => {
  const user = await currentUser(req)
  const r = await query('SELECT tr.*, ts.capacity FROM tour_requests tr JOIN tour_slots ts ON ts.id=tr.slot_id JOIN venues v ON v.id=ts.venue_id WHERE tr.id=$1 AND v.manager_id=$2', [req.params.id, user.id])
