  $('content').insertAdjacentHTML('afterbegin', `<section class="panel"><h3 data-testid="text-venue-form-title">New venue</h3><div class="grid cols-3"><input data-testid="input-venue-name" id="vName" placeholder="Name"><input data-testid="input-venue-address" id="vAddress" placeholder="Address"><input data-testid="input-venue-postcode" id="vPostcode" placeholder="Postcode"><textarea data-testid="input-venue-description" id="vDescription" placeholder="Description (200+ characters)"></textarea><input data-testid="input-venue-contact" id="vContact" placeholder="Contact info"><input data-testid="input-min-guests" id="vMin" type="number" placeholder="Min guests"><input data-testid="input-max-guests" id="vMax" type="number" placeholder="Max guests"><input data-testid="input-base-fee" id="vBase" type="number" placeholder="Base fee"><input data-testid="input-person-fee" id="vPerson" type="number" placeholder="Per-person fee"><select data-testid="input-venue-type" id="vType"><option>Indoor</option><option>Outdoor</option><option>Both</option></select><select data-testid="input-venue-status" id="vStatus"><option>Active</option><option>Inactive</option></select><input data-testid="input-image-url" id="vImage" placeholder="Main image URL"><button data-testid="button-create-venue" onclick="createVenue()">Create venue</button></div></section>`)
}
async function createVenue() { try { await api('/api/venues', { method: 'POST', body: JSON.stringify({ name: $('vName').value, address: $('vAddress').value, postcode: $('vPostcode').value, description: $('vDescription').value, contact_info: $('vContact').value, min_guests: $('vMin').value, max_guests: $('vMax').value, base_fee: $('vBase').value, per_person_fee: $('vPerson').value, venue_type: $('vType').value, status: $('vStatus').value, image_url: $('vImage').value }) }); await managerDashboard() } catch(e) { msg(e.message) } }
function tourRequest(r) { return `<div class="card card-body" data-testid="card-tour-request-${r.id}"><p data-testid="text-tour-request-${r.id}"><b>${r.venue_name}</b> tour for ${r.partner_names || 'couple'} on ${fmtDate(r.date)} ${r.time} · ${r.status}</p><button data-testid="button-approve-tour-${r.id}" onclick="actTour(${r.id},'approve')">Approve</button> <button class="secondary" data-testid="button-deny-tour-${r.id}" onclick="actTour(${r.id},'deny')">Deny</button></div>` }
function weddingRequest(r) { return `<div class="card card-body" data-testid="card-wedding-request-${r.id}"><p data-testid="text-wedding-request-${r.id}"><b>${r.venue_name}</b> ${fmtDate(r.date)} · ${r.guest_count} guests · ${money(Number(r.base_fee)+Number(r.per_person_fee)*Number(r.guest_count))} · ${r.status}</p><button data-testid="button-confirm-wedding-${r.id}" onclick="actWedding(${r.id},'confirm')">Confirm</button> <button class="secondary" data-testid="button-decline-wedding-${r.id}" onclick="actWedding(${r.id},'decline')">Decline</button></div>` }
async function actTour(id, action) { try { await api(`/api/tour-requests/${id}/${action}`, { method: 'POST' }); await managerDashboard() } catch(e) { msg(e.message) } }
async function actWedding(id, action) { try { await api(`/api/weddings/${id}/${action}`, { method: 'POST', body: JSON.stringify({ reason: 'Unavailable' }) }); await managerDashboard() } catch(e) { msg(e.message) } }

init()
"}

